def min_interval_removals(intervals):
    if not intervals:
        return 0
    ivs = sorted(intervals, key=lambda iv: iv[1])
    kept_end = None
    kept = 0
    for start, end in ivs:
        if kept_end is None or start >= kept_end:
            kept += 1
            kept_end = end
    return len(ivs) - kept
